#include <iostream>
#include <iomanip>
#include <cstdint>

void displayBits(uint32_t value) {
    constexpr int TOTAL_BITS = sizeof(uint32_t) * 8;
    constexpr uint32_t MASK = 1u << (TOTAL_BITS - 1);

    std::cout << std::setw(10) << value << " = ";
    for (int i = 1; i <= TOTAL_BITS; ++i) {
        std::cout << ((value & MASK) ? '1' : '0');
        value <<= 1;
        if (i % 8 == 0 && i < TOTAL_BITS) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    uint32_t number1 = 2179876355u;
    uint32_t mask = 1u;

    std::cout << "The result of combining the following\n";
    displayBits(number1);
    displayBits(mask);
    std::cout << "using the bitwise AND operator & is\n";
    displayBits(number1 & mask);

    return 0;
}

#include <iostream>
#include <iomanip>
#include <cstdint>

void displayBits(uint32_t value) {
    constexpr int TOTAL_BITS = sizeof(uint32_t) * 8;
    constexpr uint32_t MASK = 1u << (TOTAL_BITS - 1);

    std::cout << std::setw(10) << value << " = ";
    for (int i = 1; i <= TOTAL_BITS; ++i) {
        std::cout << ((value & MASK) ? '1' : '0');
        value <<= 1;
        if (i % 8 == 0 && i < TOTAL_BITS) {
            std::cout << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    // Demonstrate bitwise inclusive OR
    uint32_t number1 = 15u;
    uint32_t setBits = 241u;
    std::cout << "The result of combining the following\n";
    displayBits(number1);
    displayBits(setBits);
    std::cout << "using the bitwise inclusive OR operator | is\n";
    displayBits(number1 | setBits);

    // Demonstrate bitwise exclusive OR
    number1 = 139u;
    uint32_t number2 = 199u;
    std::cout << "\nThe result of combining the following\n";
    displayBits(number1);
    displayBits(number2);
    std::cout << "using the bitwise exclusive OR operator ^ is\n";
    displayBits(number1 ^ number2);

    // Demonstrate bitwise complement
    number1 = 21845u;
    std::cout << "\nThe one's complement of\n";
    displayBits(number1);
    std::cout << "is\n";
    displayBits(~number1);

    return 0;
}
